//! The generated indexes, rendered into strings: the rule index, and one per file-register
//! instance.
//!
//! It is a committed file, gated on being current. **Rendering returns a
//! `String`; nothing here writes.** The implementation this replaces regenerated by writing
//! the file, comparing, and writing the old bytes back — a check that mutates the tree it is
//! checking, which is why the merge check's history replay needs a discarding checkout
//! between commits. A comparison against a string needs neither.

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::path::PathBuf;

use rules::{Corpus, RuleNumber};

use crate::entity::{entry_id, Anchors, Home};
use crate::manifest::{Manifest, Register, Shape};
use crate::model::{Document, Model};
use crate::scan::Observation;

/// How a document is named in an index: its project-relative path, whatever holds it.
///
/// One naming for every document. The shortened form the interpretation register had was a
/// second one, and it named a file the reader could not grep for.
pub fn label(doc: &Document) -> String {
    doc.rel.display().to_string()
}

/// The relative path from `dir` to `target`, the way a renderer resolves a link in a file
/// inside `dir`.
///
/// The upward segments this produces are legal here and nowhere else: both generated
/// indexes sit outside the walk, and generated text cannot go stale, which is what the
/// upward ban in hand-written links exists against.
fn rel_from(dir: &std::path::Path, target: &std::path::Path) -> std::path::PathBuf {
    let dir_parts: Vec<_> = dir.components().collect();
    let target_parts: Vec<_> = target.components().collect();
    let common = dir_parts
        .iter()
        .zip(&target_parts)
        .take_while(|(a, b)| a == b)
        .count();
    let mut out = std::path::PathBuf::new();
    for _ in common..dir_parts.len() {
        out.push("..");
    }
    for part in &target_parts[common..] {
        out.push(part);
    }
    out
}

/// Every rule the live files cite, and where, as `document · heading`.
///
/// The heading is tracked down the file, and **a heading line is applied before the rule
/// numbers on that same line**: a rule named in a heading belongs under that heading, not
/// under the one above it. The scanner emits the observations in the other order, so this
/// reorders them per line rather than replaying them as they arrive.
fn citations(model: &Model, index_dir: &std::path::Path) -> BTreeMap<Sort, Vec<String>> {
    let mut out: BTreeMap<Sort, BTreeSet<String>> = BTreeMap::new();
    for doc in model.documents() {
        // A markdown link, so a reader follows the row where a renderer shows the page.
        let name = format!(
            "[{}]({})",
            label(doc),
            rel_from(index_dir, &doc.rel).display()
        );
        let mut heading = String::new();
        let mut by_line: BTreeMap<u32, Vec<&Observation>> = BTreeMap::new();
        for l in &doc.observations {
            by_line.entry(l.line).or_default().push(&l.what);
        }
        for (_, observations) in by_line {
            if let Some(Observation::Heading { text, .. }) = observations
                .iter()
                .find(|o| matches!(o, Observation::Heading { .. }))
                .copied()
            {
                // Everything from an em dash onwards is the statement, not the name.
                heading = text.split('—').next().unwrap_or(text).trim().to_string();
            }
            for o in observations {
                if let Observation::RuleToken(rule) = o {
                    let where_ = if heading.is_empty() {
                        name.clone()
                    } else {
                        format!("{name} · {heading}")
                    };
                    out.entry(Sort(rule.clone())).or_default().insert(where_);
                }
            }
        }
    }
    out.into_iter()
        .map(|(k, v)| (k, v.into_iter().collect()))
        .collect()
}

/// A rule number in the order the rule index is generated in: section, then the printed text.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Sort(pub RuleNumber);

impl Ord for Sort {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.0.cmp_index(&other.0)
    }
}

impl PartialOrd for Sort {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

/// `path@rules@index.md`: every rule cited, and what depends on it.
///
/// This is what makes a bump actionable — when a rule changes or is renumbered, it says
/// exactly what has to be re-read.
pub fn rule_index(model: &Model, manifest: &Manifest, corpus: &Corpus, pinned: &str) -> String {
    let cites = citations(model, &manifest.rules().dir);
    let (known, unknown): (Vec<_>, Vec<_>) = cites
        .iter()
        .partition(|(Sort(rule), _)| corpus.contains(rule));

    let mut out = String::new();
    out.push_str("# Rule citation index\n\n");
    // The provenance line names the command that regenerates the file, because a generated
    // file a reader cannot regenerate is a file they will edit by hand.
    out.push_str("**Generated — do not edit.** `cargo knowledge index`\n\n");
    out.push_str(
        "Every Comprehensive Rule the live files cite, and where. This is what makes a\n\
         rules bump actionable: when a rule changes or is renumbered, this says exactly what\n\
         depends on it — documents today, code and tests once they exist. The survey is\n\
         excluded, being frozen against its own release.\n\n",
    );
    out.push_str(&format!(
        "Pinned rules release: `{pinned}` · {} rules cited\n\n",
        known.len()
    ));
    out.push_str("| Rule | Cites | Where |\n|---|---|---|\n");
    for (Sort(rule), where_) in &known {
        out.push_str(&format!(
            "| `{rule}` | {} | {} |\n",
            where_.len(),
            where_.join("<br>")
        ));
    }
    if !unknown.is_empty() {
        let names: Vec<String> = unknown
            .iter()
            .map(|(Sort(r), _)| format!("`{r}`"))
            .collect();
        out.push_str(&format!(
            "\n**Not rules in this release** (citation error, or prose that parses as one): {}\n",
            names.join(", ")
        ));
    }
    out
}

/// One row of a file-register index: where it sits, what it sorts by, and what it prints.
struct Row {
    /// The group subdirectory the entry sits in, `None` at the instance's top level.
    group: Option<String>,
    id: String,
    /// One value per declared metadata key, in the key order the header prints.
    values: Vec<String>,
    title: String,
    /// The entry's path relative to the index's own directory.
    link: String,
}

/// The index of one file-register instance, byte for byte as `check::generated` compares it.
///
/// The shape is a contract, not a rendering choice: `design@knowledge@a-file-register-index-is-rows`
/// states it, and a generator that disagreed with the committed bytes would fail the gate on
/// every entry edit.
///
/// **The rows come from the walked entries, not from the instance's declarations.** A group is
/// the subdirectory an entry sits in, so a group nobody declared still lists its entries and
/// a declared group holding none prints no heading. `check::registers` is what reports the
/// declaration, and an index that hid an entry because of it would be a listing that stops
/// listing.
pub fn file_register_index(model: &Model, register: &Register, home: &Home) -> String {
    let keys: Vec<&str> = register.metadata.iter().map(|(k, _)| k.as_str()).collect();
    let mut rows: Vec<Row> = Vec::new();
    for doc in model.documents() {
        let Some(id) = entry_id(&doc.rel, &home.dir) else {
            continue;
        };
        let inside = doc.rel.strip_prefix(&home.dir).unwrap_or(&doc.rel);
        let parts: Vec<String> = inside
            .components()
            .map(|c| c.as_os_str().to_string_lossy().into_owned())
            .collect();
        rows.push(Row {
            group: (parts.len() > 1).then(|| parts[0].clone()),
            values: keys.iter().map(|k| metadata(doc, k)).collect(),
            title: title(doc, &id),
            link: parts.join("/"),
            id,
        });
    }
    // Ungrouped first, because `None` orders before `Some`; then by the first metadata key,
    // then by id, per the contract. A register declaring no key sorts by id alone, which is
    // what an empty first value gives.
    rows.sort_by(|a, b| {
        (&a.group, a.values.first(), &a.id).cmp(&(&b.group, b.values.first(), &b.id))
    });

    let mut out = String::from("**Generated — do not edit.** `cargo knowledge index`\n\n");
    out.push_str(&format!("{} entries\n", rows.len()));
    let mut open: Option<&Option<String>> = None;
    for row in &rows {
        if open != Some(&row.group) {
            open = Some(&row.group);
            if let Some(group) = &row.group {
                out.push_str(&format!("\n## {group}\n"));
            }
            let mut header: Vec<&str> = keys.clone();
            header.push("title");
            out.push_str(&format!("\n| {} |\n", header.join(" | ")));
            out.push_str(&format!("| {} |\n", vec!["---"; header.len()].join(" | ")));
        }
        let mut cells: Vec<String> = row.values.iter().map(|v| cell(v)).collect();
        cells.push(format!(
            "[{}]({})",
            link_text(&row.title),
            link_target(&row.link)
        ));
        out.push_str(&format!("| {} |\n", cells.join(" | ")));
    }
    out
}

/// One frontmatter value, or the empty string where the entry carries none.
///
/// **Empty rather than a placeholder.** A missing or unparseable metadata value is already a
/// `registers` finding, and writing a word into the cell would put a value in the index that
/// no entry carries.
fn metadata(doc: &Document, key: &str) -> String {
    doc.parsed
        .frontmatter
        .as_ref()
        .and_then(|f| f.as_ref().ok())
        .and_then(|keys| keys.iter().find(|(k, _)| k == key))
        .map(|(_, v)| v.clone())
        .unwrap_or_default()
}

/// The entry's level-one title as written, or its id where it carries no title.
fn title(doc: &Document, id: &str) -> String {
    doc.observations
        .iter()
        .find_map(|l| match &l.what {
            Observation::Heading { level: 1, text } => Some(text.clone()),
            _ => None,
        })
        .unwrap_or_else(|| id.to_string())
}

/// A value as one table cell: a pipe inside it would end the cell and shift every column.
fn cell(text: &str) -> String {
    text.replace('|', r"\|")
}

/// A title as the text of a markdown link.
///
/// A `]` closes the link early, and a `(` after it is then read as the destination of the
/// truncated link — so a title holding `](` **redirects the row at whatever it names**. The
/// index is outside the walk by construction, so no link check would ever see it. A pipe ends
/// the cell as it does anywhere else.
fn link_text(text: &str) -> String {
    let mut out = String::new();
    for c in text.chars() {
        if matches!(c, '|' | '[' | ']') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

/// An entry's path as a link destination.
///
/// The pipe is the cell's, as everywhere. The inline destination form additionally ends at the
/// first space and cannot hold an unbalanced parenthesis, so a path with either takes the
/// angle-bracket form, which ends only at an unescaped `>`. Both are reachable through a group
/// directory, whose name no grammar constrains.
fn link_target(path: &str) -> String {
    let escaped = path.replace('|', r"\|");
    if escaped
        .chars()
        .any(|c| c.is_whitespace() || matches!(c, '(' | ')'))
    {
        return format!("<{}>", escaped.replace('<', r"\<").replace('>', r"\>"));
    }
    escaped
}

/// Every file-register index of the project, with the bytes it should hold.
///
/// One list, read by `cargo knowledge index` and by `check::generated` both, so the writer and
/// the gate cannot disagree about which files exist or what is in them.
///
/// **An instance whose directory is not there contributes nothing.** Generating into it would
/// create a register home as a side effect of a listing; the missing home is a `registers`
/// finding, which is where a reader is told about it.
pub fn file_register_indexes(
    model: &Model,
    manifest: &Manifest,
    directories: &HashSet<PathBuf>,
) -> Vec<(PathBuf, String)> {
    let mut out = Vec::new();
    for (_, register, home) in Anchors::of(manifest).instances() {
        if register.shape != Shape::File || !directories.contains(&home.dir) {
            continue;
        }
        out.push((
            home.index.clone(),
            file_register_index(model, register, &home),
        ));
    }
    out.sort_by(|a, b| a.0.cmp(&b.0));
    // Two registers sharing one home is a declaration `check::registers` reports; writing the
    // same destination twice in one run is not this command's way of saying so.
    out.dedup_by(|a, b| a.0 == b.0);
    out
}

/// Every path this tool writes a generated file at: the rule index, and one index per
/// file-register instance, whether or not the directory is there.
///
/// **This is what puts a generated file outside the walk by construction.** The set is
/// derived from the manifest's corpus and register instances, so no `[walk] skip-files` row
/// names one and a new instance cannot be created with its index inside the walk. A
/// generated file that was walked would be read as a document: the rule index's table cells
/// carry every slug the tree defines, and each read as a definition where none may sit.
pub fn generated_paths(manifest: &Manifest) -> HashSet<PathBuf> {
    let mut out = generated_index_paths(manifest);
    out.insert(manifest.rules().dir.join("index.md"));
    out
}

/// Every path this tool generates a file-register index at, whether or not the directory is
/// there. The rule index is not one; `generated_paths` is the whole set.
pub fn generated_index_paths(manifest: &Manifest) -> HashSet<PathBuf> {
    Anchors::of(manifest)
        .instances()
        .into_iter()
        .filter(|(_, register, _)| register.shape == Shape::File)
        .map(|(_, _, home)| home.index)
        .collect()
}

/// Greedy wrap on whitespace that never breaks a word, matching the generator being replaced.
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        if !line.is_empty() && line.chars().count() + 1 + word.chars().count() > width {
            out.push(std::mem::take(&mut line));
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    if !line.is_empty() {
        out.push(line);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    // Every fixture is inline: the checker reads no string literal of its own source, per
    // `design@knowledge@checker-source-literals-are-data`.

    /// A declaration whose rules directory and register directory are one level deep.
    fn declaring() -> Manifest {
        let text = "[project]\nname = \"a-project\"\ncomponents = []\n\n\
             [walk]\nskip-dirs = []\nskip-files = []\n\n\
             [rules]\ndir = \"r\"\ntext = \"t\"\nbody-starts-at = 0\n\
             version = \"v\"\npast = \"p\"\nmanifest = \"m\"\n";
        Manifest::parse(std::path::Path::new("/nowhere"), text).expect("a declaration")
    }

    #[test]
    fn a_rule_index_row_links_relative_to_the_index_directory() {
        // A markdown link a renderer follows, with the upward segments the index's own
        // directory requires — legal here because the generated files sit outside the walk
        // and regenerate, so the link cannot go stale.
        let corpus = Corpus::parse("100.1 A mock rule body.\n", 0);
        let doc = "parts/x/doc.md";
        let model = Model::from_documents(vec![(PathBuf::from(doc), "per CR:100.1\n".to_string())]);
        let index = rule_index(&model, &declaring(), &corpus, "20200101");
        let row = format!("[{doc}](../{doc})");
        assert!(index.contains(&row), "{index}");
    }

    /// A file register named `note`, with one metadata key or with none.
    fn register(with_metadata: bool) -> Register {
        let metadata = if with_metadata {
            "\n[registers.note.metadata.status]\nvalues = [\"open\", \"closed\"]\n"
        } else {
            ""
        };
        let text = format!(
            "[project]\nname = \"a-project\"\ncomponents = []\n\n\
             [registers.note]\nscope = \"opt-in\"\nshape = \"file\"\ndir = \"notes\"\n{metadata}\n\
             [walk]\nskip-dirs = []\nskip-files = []\n\n\
             [rules]\ndir = \"r\"\ntext = \"t\"\nbody-starts-at = 0\n\
             version = \"v\"\npast = \"p\"\nmanifest = \"m\"\n"
        );
        Manifest::parse(std::path::Path::new("/nowhere"), &text)
            .expect("a declaration")
            .registers()
            .by_name("note")
            .expect("the declared register")
            .clone()
    }

    /// The home a register instance keeps at `notes/`.
    fn home() -> Home {
        Home {
            file: PathBuf::from("notes.md"),
            dir: PathBuf::from("notes"),
            readme: PathBuf::from("notes/README.md"),
            index: PathBuf::from("notes/index.md"),
            config: PathBuf::from("notes/register.toml"),
            shape: Shape::File,
        }
    }

    fn rendered(docs: Vec<(&str, &str)>, with_metadata: bool) -> String {
        let model = Model::from_documents(
            docs.into_iter()
                .map(|(p, t)| (PathBuf::from(p), t.to_string()))
                .collect(),
        );
        file_register_index(&model, &register(with_metadata), &home())
    }

    #[test]
    fn an_instance_with_no_entry_is_a_banner_a_count_and_nothing_else() {
        // The whole file, byte for byte: the shape is a contract, and a comparison against a
        // fragment of it would accept a table nobody asked for underneath.
        assert_eq!(
            rendered(vec![("notes/README.md", "# The head\n")], true),
            "**Generated — do not edit.** `cargo knowledge index`\n\n0 entries\n"
        );
    }

    #[test]
    fn the_columns_are_the_declared_keys_then_the_title_linked_to_the_file() {
        let out = rendered(
            vec![(
                "notes/one-entry.md",
                "---\nstatus: open\n---\n# The only entry\n",
            )],
            true,
        );
        assert_eq!(
            out,
            "**Generated — do not edit.** `cargo knowledge index`\n\n1 entries\n\n\
             | status | title |\n| --- | --- |\n\
             | open | [The only entry](one-entry.md) |\n"
        );
    }

    #[test]
    fn rows_sort_by_the_first_metadata_key_then_by_id_and_by_id_alone_where_none_is_declared() {
        let docs = vec![
            ("notes/b.md", "---\nstatus: open\n---\n# B\n"),
            ("notes/a.md", "---\nstatus: open\n---\n# A\n"),
            ("notes/c.md", "---\nstatus: closed\n---\n# C\n"),
        ];
        let with = rendered(docs.clone(), true);
        let order: Vec<&str> = with.lines().filter(|l| l.contains("](")).collect();
        assert_eq!(
            order,
            vec![
                "| closed | [C](c.md) |",
                "| open | [A](a.md) |",
                "| open | [B](b.md) |",
            ],
            "{with}"
        );
        // With no key declared the frontmatter is not read at all and the order is the id's.
        let without = rendered(docs, false);
        let order: Vec<&str> = without.lines().filter(|l| l.contains("](")).collect();
        assert_eq!(
            order,
            vec!["| [A](a.md) |", "| [B](b.md) |", "| [C](c.md) |"],
            "{without}"
        );
    }

    #[test]
    fn ungrouped_entries_come_first_and_each_group_takes_a_heading() {
        let out = rendered(
            vec![
                ("notes/loose.md", "---\nstatus: open\n---\n# Loose\n"),
                ("notes/zeta/one.md", "---\nstatus: open\n---\n# One\n"),
                ("notes/alpha/two.md", "---\nstatus: open\n---\n# Two\n"),
            ],
            true,
        );
        let heads: Vec<&str> = out
            .lines()
            .filter(|l| l.starts_with("## ") || l.contains("]("))
            .collect();
        assert_eq!(
            heads,
            vec![
                "| open | [Loose](loose.md) |",
                "## alpha",
                "| open | [Two](alpha/two.md) |",
                "## zeta",
                "| open | [One](zeta/one.md) |",
            ],
            "{out}"
        );
        // The count is every entry, grouped or not.
        assert!(out.contains("\n3 entries\n"), "{out}");
    }

    #[test]
    fn the_title_is_the_level_one_heading_and_not_the_first_heading_of_any_level() {
        // A file register's entry owes a level-one title; one that opens on a deeper heading is
        // a `registers` finding, and the index falls back to the id rather than promoting it.
        let out = rendered(
            vec![(
                "notes/deep.md",
                "---\nstatus: open\n---\n## A level-two opening\n\n# The real title\n",
            )],
            true,
        );
        assert!(out.contains("[The real title](deep.md)"), "{out}");
        assert!(!out.contains("A level-two opening"), "{out}");
    }

    #[test]
    fn an_entry_with_no_value_and_no_title_still_takes_a_row() {
        // Both are `registers` findings. The index is a listing of what is there, so an entry
        // the shape check refuses is still listed, under its id and an empty cell.
        let out = rendered(vec![("notes/no-head.md", "Just prose.\n")], true);
        assert!(out.contains("|  | [no-head](no-head.md) |"), "{out}");
    }

    #[test]
    fn every_half_of_a_row_is_escaped_against_the_syntax_it_sits_in() {
        // Each of these produces a well-formed entry that `registers` reports nothing about, so
        // the index is the only thing standing between the tree and a corrupt table.
        let out = rendered(
            vec![
                (
                    "notes/piped.md",
                    "---\nstatus: open\n---\n# A title with a | in it\n",
                ),
                (
                    "notes/bracket.md",
                    // The dangerous one: `](` closes the link early and what follows becomes
                    // the destination, so the row would point wherever the title says.
                    "---\nstatus: open\n---\n# A title with ](evil.md) inside\n",
                ),
                (
                    // A group name is a directory name, which no grammar constrains, and it
                    // reaches the row through the link's destination.
                    "notes/pi|pe/z.md",
                    "---\nstatus: open\n---\n# Z\n",
                ),
                ("notes/a b(c)/y.md", "---\nstatus: open\n---\n# Y\n"),
            ],
            true,
        );
        // Every row has exactly three cell separators: two columns and the closing pipe.
        for line in out.lines().filter(|l| l.contains("](")) {
            let unescaped = line
                .char_indices()
                .filter(|(i, c)| *c == '|' && !line[..*i].ends_with('\\'))
                .count();
            assert_eq!(unescaped, 3, "{line}");
        }
        assert!(
            out.contains(r"| open | [A title with a \| in it](piped.md) |"),
            "{out}"
        );
        assert!(
            out.contains(r"| open | [A title with \](evil.md) inside](bracket.md) |"),
            "{out}"
        );
        assert!(out.contains(r"[Z](pi\|pe/z.md)"), "{out}");
        // A space or a parenthesis ends an inline destination, so the path takes the
        // angle-bracket form instead.
        assert!(out.contains("[Y](<a b(c)/y.md>)"), "{out}");
    }

    #[test]
    fn the_generated_list_is_sorted_by_destination_and_names_each_once() {
        // The dedup below removes CONSECUTIVE duplicates, so it does nothing unless the list is
        // sorted first: dropping the sort silently disarms it.
        let text = "[project]\nname = \"a-project\"\ncomponents = [\"parts/b\", \"parts/a\"]\n\n\
             [walk]\nskip-dirs = []\nskip-files = []\n\n\
             [rules]\ndir = \"r\"\ntext = \"t\"\nbody-starts-at = 0\n\
             version = \"v\"\npast = \"p\"\nmanifest = \"m\"\n";
        let manifest = Manifest::parse(std::path::Path::new("/nowhere"), text).expect("declared");
        let model = Model::from_documents(Vec::new());
        let dirs: HashSet<PathBuf> = [
            "docs/open-issues",
            "parts/a/docs/open-issues",
            "parts/b/docs/open-issues",
        ]
        .iter()
        .map(PathBuf::from)
        .collect();
        let paths: Vec<String> = file_register_indexes(&model, &manifest, &dirs)
            .into_iter()
            .map(|(rel, _)| rel.display().to_string())
            .collect();
        assert_eq!(
            paths,
            vec![
                "docs/open-issues/index.md".to_string(),
                "parts/a/docs/open-issues/index.md".to_string(),
                "parts/b/docs/open-issues/index.md".to_string(),
            ],
            "the components are declared b before a, and the list is sorted"
        );
        // And the set of destinations is what `generated_index_paths` names, with no duplicate.
        let declared = generated_index_paths(&manifest);
        assert_eq!(declared.len(), paths.len());
    }

    #[test]
    fn one_home_shared_by_two_registers_is_one_destination_and_not_two() {
        // Two registers declaring one directory is a `registers` finding. Until it is repaired,
        // this command must not write the same destination twice in one run.
        let text = "[project]\nname = \"a-project\"\ncomponents = []\n\n\
             [locations.notes]\npath = \"notes\"\nregisters = [\"one\", \"two\"]\n\n\
             [registers.one]\nscope = \"opt-in\"\nshape = \"file\"\ndir = \"shared\"\n\n\
             [registers.two]\nscope = \"opt-in\"\nshape = \"file\"\ndir = \"shared\"\n\n\
             [walk]\nskip-dirs = []\nskip-files = []\n\n\
             [rules]\ndir = \"r\"\ntext = \"t\"\nbody-starts-at = 0\n\
             version = \"v\"\npast = \"p\"\nmanifest = \"m\"\n";
        let manifest = Manifest::parse(std::path::Path::new("/nowhere"), text).expect("declared");
        let model = Model::from_documents(Vec::new());
        let dirs: HashSet<PathBuf> = [PathBuf::from("notes/shared")].into_iter().collect();
        assert_eq!(file_register_indexes(&model, &manifest, &dirs).len(), 1);
    }

    #[test]
    fn wrapping_never_breaks_a_word_and_fills_greedily() {
        assert_eq!(wrap("aaa bbb ccc", 7), vec!["aaa bbb", "ccc"]);
        assert_eq!(wrap("averylongword", 4), vec!["averylongword"]);
        assert_eq!(wrap("", 10), Vec::<String>::new());
    }
}
